import{_ as o,o as r,c as l,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"04 趋势预测方法论（知识手册）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/04_趋势预测方法论.md","filePath":"topics/tianya/handbook/04_趋势预测方法论.md"}'),s={name:"topics/tianya/handbook/04_趋势预测方法论.md"};function u(i,t,q,g,a,e){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="_04-趋势预测方法论-知识手册" tabindex="-1">04 趋势预测方法论（知识手册） <a class="header-anchor" href="#_04-趋势预测方法论-知识手册" aria-label="Permalink to &quot;04 趋势预测方法论（知识手册）&quot;">​</a></h1><blockquote><p>来源：24 篇天涯实测预测帖（帖号即 /tmp/thunder/texts/ 编号，如 54、72、135）。本手册不复述&quot;他们预测了什么&quot;，只提炼<strong>怎么预测才准</strong>：每节给出操作步骤、判定标准与原帖实例。适用对象：需要在不确定环境中做资产、职业、行业决策的普通人。</p></blockquote><hr><h2 id="一、命中率分层定律-预测前先选对颗粒度" tabindex="-1">一、命中率分层定律：预测前先选对颗粒度 <a class="header-anchor" href="#一、命中率分层定律-预测前先选对颗粒度" aria-label="Permalink to &quot;一、命中率分层定律：预测前先选对颗粒度&quot;">​</a></h2><p>对 24 篇帖子的实测统计，预测可分为三层，准确率呈稳定梯度：</p><table tabindex="0"><thead><tr><th>层级</th><th>内容</th><th>实测命中率</th><th>代表案例</th></tr></thead><tbody><tr><td>结构层</td><td>制度约束、政策工具选择、人口、行业兴衰</td><td>约 7–8 成</td><td>5(kkndme 调控五连中)、122/195(老仇通缩与人口)、14(Kulese 放水论)、18(143 行业名单)</td></tr><tr><td>方向层</td><td>通胀/通缩、资产牛熊、汇率升贬</td><td>约 5 成</td><td>3(169 黄金对) vs 2/7(汇率全错)、17(199 只对&quot;滞&quot;不对&quot;胀&quot;)</td></tr><tr><td>点位层</td><td>指数点位、汇率终值、崩盘日期</td><td>约 3 成</td><td>7(上证 1900–2100)、6(纳指 8500 见顶)、4(A股一万点)、9(铁龙 40 元)——全部落空；唯一命中为 11(老仇 2020-03-01)</td></tr></tbody></table><p><strong>为什么存在这个梯度？四个原因：</strong></p><ol><li><strong>对手的选项集不同。</strong> 结构层猜的是决策者的&quot;选项&quot;：降准还是加息、征不征房产税、限不限购——选项通常只有 3–5 个，且受制度硬约束。点位层猜的是连续变量：市场点位是所有参与者预期的合成，你没有任何信息优势，且错一分就是全错，没有部分得分。</li><li><strong>外生冲击的杀伤半径不同。</strong> 贸易战（2018）、疫情（2020）这类外生冲击会打乱方向，但打不乱结构（它不改变&quot;政府怕失业、银行怕坏账&quot;）。所以结构判断自带抗震性。</li><li><strong>反馈周期不同。</strong> 结构判断以年计，过程中可以持续观察、中途修正（Kulese 在 14 中每季修正仓位建议）；点位判断一锤定音，没有修正机会。</li><li><strong>容错空间不同。</strong> 结构判断的收益是分布式的（&quot;避开汽车行业&quot;省下的损失逐年累积）；点位判断的收益是事件式的，赌错即出局。</li></ol><p><strong>正确用法（判定标准）：</strong></p><ul><li>结构层结论 → 可写入决策、可配大仓位。例：读到 5 的&quot;房产税几年内不会出&quot;，就不必为房产税抛售自住房。</li><li>方向层结论 → 只配对冲与缓冲（现金、黄金、保险），不押单一情景。例：169 看对黄金，但同一作者看 A 股就只能给&quot;台阶还得上&quot;的模糊方向。</li><li>点位层结论 → 只用于挂单分批（&quot;跌到 X 买一成&quot;），<strong>禁止</strong>作为&quot;何时行动&quot;的触发器。</li></ul><p><strong>反例</strong>：9(系统方法论)把点位（铁龙 40 元）当卖点，8(高级工程狮A)把燕郊抄底当结论——能力不弱，但颗粒度选错，全军覆没。</p><hr><h2 id="二、利益分析法-五步预测流程-通用性最强的工具" tabindex="-1">二、利益分析法：五步预测流程（通用性最强的工具） <a class="header-anchor" href="#二、利益分析法-五步预测流程-通用性最强的工具" aria-label="Permalink to &quot;二、利益分析法：五步预测流程（通用性最强的工具）&quot;">​</a></h2><p>源头是 5(kkndme)的方法论自白：「辨别利益是看透一切事物真相的武器」与 14(Kulese)的&quot;政治赎买&quot;论——政策不是最优解的产物，是各主体在约束下最省力选择的产物。</p><p><strong>五步操作：</strong></p><ol><li><strong>找决策者</strong>：不是抽象的&quot;国家&quot;，而是具体有能力、有动机改变局面的主体（中央、地方、央行、银行、居民、外部对手）。</li><li><strong>列目标函数</strong>：他要什么？按优先级排序（收入最大化？风险最小化？稳定压倒一切？）。</li><li><strong>算约束</strong>：钱从哪来、谁会反对、时间窗口多大、哪些过去的选择锁死了现在的路。</li><li><strong>推最小阻力路径</strong>：在&quot;目标 × 约束&quot;下，阻力最小的行动序列就是未来。</li><li><strong>给失效条件</strong>：写下&quot;如果 X 发生，此推演作废&quot;。</li></ol><p><strong>示范一：kkndme 调控推演（帖 5，2010 年语境）</strong></p><ul><li><strong>决策者</strong>：中央（唯一能定规则者）；配角为地方、开发商、银行、炒房客。</li><li><strong>目标函数</strong>：中央 = 防金融风险 + 不担&quot;房价崩盘&quot;的骂名 + 让国家队低价进场；地方 = 卖地收入最大化；两者在房产税上冲突（税会伤卖地）。</li><li><strong>约束</strong>：土地财政不可替代；银行坏账记在中央账上；民意喊降价，但真降价会引爆坏账；统计数据可按需生产（帖中原话：先有结论后有数据）。</li><li><strong>最小阻力路径</strong>：不刺破泡沫，只冻结成交——提高门槛、限购限贷、清退小开发商，让国家队垄断定价与房租（公租房为伏笔）；房产税无限期拖延；税负最终转嫁房租。</li><li><strong>预言输出</strong>：调控失败、房价续涨、房产税难产、刚需成本上升、物价（蒜姜）替楼市吸金。2011–2021 十年全部兑现。</li><li><strong>失效条件（原帖未写，此处补全）</strong>：土地财政终结、或人口拐点令需求萎缩，则&quot;稀缺+精英收入&quot;定价框架失效——这正是 2021 年后发生的事。</li></ul><p><strong>方法论要点</strong>：利益分析法解释&quot;政府想做什么&quot;极强，但<strong>不直接预测&quot;政府还能不能做到&quot;</strong>。2021 年后房价普跌不是 kkndme 的利益分析错了，而是他的前提（货币永续宽松 + 需求永续）过期了。所以失效条件必须显式写出。</p><p><strong>示范二：北京毛毛黄金推演（帖 24，2006 年语境）</strong></p><ul><li><strong>决策者</strong>：美联储与各国央行（货币发行方）；全球储户（配置方）。</li><li><strong>目标函数</strong>：央行 = 保增长优先于保币值（危机时必放水，2008 证实）；储户 = 保值。</li><li><strong>约束</strong>：全球约 7 万亿美元过剩资金找不到实体出路，只能在金融市场内循环；黄金供给刚性且产能下降；美元体系依赖持续发债。</li><li><strong>最小阻力路径</strong>：纸币购买力长期递减，黄金相对购买力稳定 → 以美元计的金价长期上行；且每次货币动荡都提醒人们想起黄金。</li><li><strong>预言输出</strong>：黄金 2000 美元上方（2011 破 1900、2020 后长牛至 3000+）；操作原则「把自己的资产折算成黄金来看」。</li><li><strong>失效条件</strong>：出现沃尔克式紧缩纪律、或央行集体抛售黄金——2006–2025 未发生，判断全程成立。</li></ul><p>两条示范的共同点：<strong>输出的是&quot;倾向与机制&quot;，不是数值</strong>。利益分析的强项是政策与制度（几乎不会大错），弱项是市场价格与外部冲击（经常大错）——这与第一节的分层定律完全吻合。</p><p><strong>速查模板（帖 14，Kulese 版，一分钟版利益分析）</strong>：当没有时间做五步时，用这条压缩式——&quot;政府在什么条件下会被迫做什么？&quot;Kulese 的原推演：中国治理模式下，失业与坏账是政治底线 → 一旦失业率高企，政府必大规模放水 → 放水在生产过剩体制下只推资产、不推物价 → 结论：危机时加仓核心资产、平时留现金等错杀。2024–2025 的政策组合拳逐条命中。适用范围：财政货币政策类判断；不适用于市场定价类判断。</p><p><strong>常见错误</strong>：把&quot;决策者应该做什么&quot;当&quot;决策者会做什么&quot;。利益分析预测的是后者——目标函数里&quot;稳定&quot;权重高于&quot;效率&quot;时，再明显的好政策也不会出台；此时正确的预测是&quot;它不会发生&quot;，而不是&quot;它不该发生却会发生&quot;。</p><hr><h2 id="三、周期定位法-先定-我们在周期哪里-再谈预测" tabindex="-1">三、周期定位法：先定&quot;我们在周期哪里&quot;，再谈预测 <a class="header-anchor" href="#三、周期定位法-先定-我们在周期哪里-再谈预测" aria-label="Permalink to &quot;三、周期定位法：先定&quot;我们在周期哪里&quot;，再谈预测&quot;">​</a></h2><p><strong>老仇三部曲（122/184/195）的周期框架：</strong></p><ul><li>核心公式：「在经济扩张期努力加大杠杆，在经济收缩期努力降低杠杆」；&quot;5–8 年的经济调整是必然的，低效率部分需要一次彻底出清&quot;。</li><li>周期的三个驱动：货币（M2）× 人口 × 技术；其中人口是慢变量、最可靠（&quot;出生率跳水，从尿布到房屋都可能需求不足&quot;）。</li><li>观测指标：利率与降准方向、M2 增速、居民杠杆率、就业压力、资产&quot;蓄水池&quot;是否失效（房市吸金能力下降则水漫向消费品）、城市人口增减。</li></ul><p><strong>2020-03-01 美股崩盘推演还原（帖 195 末尾，可复用的操作样本）：</strong></p><ol><li><strong>基本面定方向</strong>：判断全球经济将进入大回调（&quot;A 股 2700 的底部很虚&quot;）。</li><li><strong>技术面定时机</strong>：不追空，等反弹衰竭——&quot;美股再上去就是做空好时机&quot;。一周后美股四次熔断。</li><li><strong>风控定生死</strong>：明言&quot;金融市场没有稳赢的策略……杠杆交易风险极高，不建议大家介入&quot;。</li></ol><p>方法论价值：<strong>三层分工，顺序不可颠倒</strong>——先用基本面定方向，再用技术面找介入点，最后用仓位管理决定你能否活着看到判断兑现。多数人死于把第三步放在第一步之前。</p><p><strong>&quot;周期的尾声&quot;判据清单（帖 135，时代之；逐条打分，命中 ≥4 条即切换防御姿态）：</strong></p><ol><li>全社会杠杆率创新高（帖中对照：危机国 100–200%，当时中国 250%+）；</li><li>软着陆窗口关闭——去杠杆刚开始就因阵痛重新加杠杆（2019Q1 证实）；</li><li>价格上涨依赖新买家进场而非盈利改善（新股民开户数、首购房年龄提前、学区房提前囤积）；</li><li>刺激政策边际失效（降准后 M2 仍起不来、社融仍弱）；</li><li>无业绩的标的轮番领涨（&quot;网红股&quot;现象）；</li><li>债务违约从边缘向核心蔓延（P2P → 银行理财 → 信托 → 城投）。</li></ol><p><strong>&quot;蓄水池&quot;机制（帖 122/195，老仇的独门观察，可作周期定位的温度计）</strong>：中国过去二十年有三大蓄水池——农村（就业蓄水池）、房市（资金蓄水池）、铁公基（增长蓄水池）。蓄水池有水时，超发货币被吸收，物价不显；蓄水池见底时（房市量缩、基建边际收益转负），同一剂货币的副作用会显形。因此观察&quot;蓄水池水位&quot;比观察 CPI 更早给出周期位置：2019 年老仇判断&quot;房市是表，金融是里，M2 若继续扩张必推高基础消费品或压垮消费&quot;，正是用这个温度计读出的。</p><p><strong>使用纪律</strong>：周期判断用于<strong>切换姿态</strong>（攻转守、加杠杆转降杠杆），不用于预测崩盘日期。135 自己在&quot;周期尾声&quot;的判断下做出&quot;纳指 8500 三重顶&quot;的点位预测，恰是违反此纪律的病例。</p><hr><h2 id="四、人口与行业兴衰预测-从-谁在变老-变少-推-什么会涨-会死" tabindex="-1">四、人口与行业兴衰预测：从&quot;谁在变老/变少&quot;推&quot;什么会涨/会死&quot; <a class="header-anchor" href="#四、人口与行业兴衰预测-从-谁在变老-变少-推-什么会涨-会死" aria-label="Permalink to &quot;四、人口与行业兴衰预测：从&quot;谁在变老/变少&quot;推&quot;什么会涨/会死&quot;&quot;">​</a></h2><p><strong>四步推演链：</strong></p><ol><li><strong>找人口结构变量</strong>：出生率、劳动年龄占比、老龄化率、城镇化率、城市人口净流入/流出。</li><li><strong>映射需求曲线</strong>：每个年龄段对应一组需求——教育/婚房/母婴 → 改善房/汽车 → 医疗/养老/服务。</li><li><strong>判断可逆性</strong>：人口是慢变量，需求转向后十年不可逆；政策只能推迟不能取消（二胎放开无效即验证）。</li><li><strong>加政策乘数</strong>：政策是放大器（军工、国产替代）或天花板（双减对教培）。</li></ol><p><strong>原帖实例与判定标准：</strong></p><ul><li>11(195)老仇：「出生率跳水→从尿布到房屋需求不足→127 个城市常住人口收缩且将扩大」→ 2016–2025 全部兑现。判定标准：<strong>需求不可逆 + 数据可交叉验证（户籍、小学在校数）</strong>。</li><li>18(143)李院士：老龄化 → 医疗康复、养老、个性化服务；年轻人 → 小众健身、视频直播、宠物、植发；人口聚集 → 大城市服务业。命中率约六成——<strong>错处全在第 4 步</strong>：教培死于双减（政策天花板）、5G 雷声大雨点小（把政策扶持当市场需求）。判定标准：<strong>政策是放大器还是天花板，要先于行业下注回答</strong>。</li><li>47(鸟树下睡懒觉的猪)职业规划帖：城市选择 = 市场容量 × 产业密度 × 容错率；小城市体制内&quot;一眼望到头&quot;，大城市试错成本高但上限高。本质是把人口流向翻译成个人职业选择——<strong>个人去向应跟随人口与产业聚集方向</strong>。</li><li>21(179)庖丁医命0 的&quot;火运&quot;名单（AI/数字化、能源、军工）：与人口无关，属于第二类需求源——<strong>国家目标函数驱动的政策性需求</strong>。提示：行业预测有两个引擎（人口需求 + 国家意志），两个引擎都要检查。</li></ul><p><strong>常见陷阱</strong>：把政策扶持当市场需求（5G、区块链）；把一次性事件当趋势（垃圾分类千亿产业，2020 后退潮）；把&quot;供给端很热闹&quot;当&quot;需求端存在&quot;。</p><hr><h2 id="五、通胀-vs-通缩-分歧复盘与判定清单" tabindex="-1">五、通胀 vs 通缩：分歧复盘与判定清单 <a class="header-anchor" href="#五、通胀-vs-通缩-分歧复盘与判定清单" aria-label="Permalink to &quot;五、通胀 vs 通缩：分歧复盘与判定清单&quot;">​</a></h2><p><strong>两大阵营档案（均为原帖立场）：</strong></p><ul><li><strong>大通胀派</strong>：3(高天无影1——地方国企负债率高，无牌降息，只能印，&quot;通胀是不可变的宿命&quot;)；17(潜龙——货币超发+成本推动：去产能与环保风暴推高上游价格)；22(庖丁——&quot;衰退与高通胀交替的螺旋式下跌&quot;)；4(天之星——&quot;被抑制的通胀终将释放&quot;)。共同逻辑：货币数量论 + 供给收缩。</li><li><strong>通缩派</strong>：10/11(老仇——房市蓄水池失效后，M2 溢出本是通胀逻辑，但需求塌陷让水无源)；14(Kulese——中国是生产过剩模式，放水只推资产不推物价，叠加流动性陷阱)。共同逻辑：有效需求不足 + 资产负债表约束。</li></ul><p><strong>判决：两边各对一半。</strong> 全球层面通胀兑现（2021–2022 美欧 CPI 冲上 9%，金价 3000+），中国层面通缩兑现（CPI 贴零、PPI 常年负、房价普跌）。归因：</p><ul><li>通胀派错在&quot;超发→物价&quot;这一步：中国的超发货币进入了地产与债务滚动，从未进入工资—物价循环；</li><li>通缩派抓住了需求主体：居民杠杆打满后，印钞只能补窟窿，造不出新需求；</li><li>通胀派对在&quot;外部输入&quot;：疫情与战争造成的供给冲击，确实带来了一轮成本推动型通胀。</li></ul><p><strong>判断通胀还是通缩的检查清单（逐条打分，多数项同向即为结论）：</strong></p><ol><li><strong>超发货币去向</strong>：进工资与消费 → 通胀；进资产与债务滚动 → 资产胀、商品缩。</li><li><strong>需求主体健康度</strong>：居民杠杆低且工资增长 → 通胀温床；居民杠杆打满、收入预期转弱 → 通缩土壤。</li><li><strong>供给端状态</strong>：主动收缩（去产能/战争/疫情）→ 成本推动通胀；产能过剩 → 通缩。</li><li><strong>债务周期位置</strong>：扩张期赤字货币化 → 通胀；出清期 → 通缩优先。</li><li><strong>政策空间</strong>：实际利率 &gt;0 → 有刺激空间；已到零/负 → 流动性陷阱，通缩黏性强。</li><li><strong>汇率</strong>：大幅贬值 → 输入型通胀；币值稳定 + 内需弱 → 通缩。</li><li><strong>工资—物价螺旋</strong>：没有工资普涨的&quot;通胀&quot;不可持续。</li><li><strong>蓄水池状态</strong>：房市股市还能吸金吗？吸金力下降 + 需求塌陷 → 连&quot;水漫消费品&quot;都不会发生。</li></ol><p>用此清单回看 2019 年：第 1、2、3、5、8 条全部指向通缩——<strong>当时多数人站错边，清单可以让你站对</strong>。</p><p><strong>清单使用要点</strong>：①八条不必全对，抓主导项——第 1 条（货币去向）与第 2 条（需求主体）权重最高，占判断的一半；②通胀派与通缩派的分歧本质是&quot;看供给端还是看需求端&quot;，清单的作用是强制你两边都打分，防止单边信仰；③结论要带时间尺度：通缩环境里也有结构性通胀（猪周期、服务价格），清单给的是&quot;大类方向&quot;，不排除局部例外——199 潜龙那句&quot;滞胀 vs 复苏五六成 vs 四五成&quot;的概率化表述，其实比任何阵营的斩钉截铁都更接近正确姿势。</p><hr><h2 id="六、预测的失效模式-六种死法-每种配一例" tabindex="-1">六、预测的失效模式：六种死法（每种配一例） <a class="header-anchor" href="#六、预测的失效模式-六种死法-每种配一例" aria-label="Permalink to &quot;六、预测的失效模式：六种死法（每种配一例）&quot;">​</a></h2><ol><li><strong>高估政策速度</strong>。病例：7(老江南&quot;有序贬值到 8&quot;)与 8(&quot;人民币升 6.4、热钱涌入&quot;)。病因：把汇率当作政府可直选的目标，忽视汇率是贸易、利差、预期的合成变量。识别特征：结论中出现&quot;必将、很快、一步到位&quot;。</li><li><strong>低估路径依赖</strong>。病例：13(大江宁静&quot;房价以人民币计价难跌&quot;——1998–2020 二十年有效，2021 后彻底失效)。病因：机制没错，前提过期（土地财政终结、需求拐点）。识别特征：一套框架十年没有修过任何参数。</li><li><strong>阴谋论陷阱</strong>。病例：16(独孤求败AH&quot;中美收入差是航母的功劳&quot;&quot;美国十年内沦为二流&quot;)。病因：用单一权力叙事替代机制分析——它能解释一切，因此不可预测任何事；2(样条曲线A&quot;升值救国&quot;)同病。识别特征：问不出&quot;这个理论会预测错什么&quot;。</li><li><strong>荐股利益冲突</strong>。病例：9(系统方法论：打赏、引流、荐铁龙&quot;目标 40 元&quot;、拉配资群)。病因：发帖人收入来自读者的行为（接盘、打赏、进群），与预测对错无关。识别特征：内容与打赏/进群/配资挂钩；预测越具体越危险。</li><li><strong>全知口吻危险信号</strong>。病例：42(exposureJINGDONG&quot;准确率仅也就 100%，一个字都不改&quot;)。四连信号：①宣称 100% 准确率（从统计学上无人可达）；②关键证据是&quot;帖子被隐藏的三十九页&quot;——不可验证；③用隐私轶事当证据（&quot;朋友公司因此避免十几亿汇兑损失&quot;）；④贬损一切同行（&quot;所有媒体砖家都在坑蒙拐骗&quot;）以抬高自己。识别特征：凡见&quot;100%&quot;+不可验证的往事+&quot;你们不合格&quot;，预测价值按零处理。</li><li><strong>玄学不可修正</strong>。病例：22/21(庖丁医命0)与 23(灵界帖)。说明：它们时点命中（2020 庚子、春节前后美股）更像运气叠加敏锐的时代直觉；真正的问题是模型<strong>无法输出失效条件</strong>——错了不能改，对了无法归因。识别特征：回答不了&quot;什么证据会让你改变结论&quot;。</li></ol><hr><h2 id="七、普通人的预测使用纪律-把预测翻译成决策" tabindex="-1">七、普通人的预测使用纪律：把预测翻译成决策 <a class="header-anchor" href="#七、普通人的预测使用纪律-把预测翻译成决策" aria-label="Permalink to &quot;七、普通人的预测使用纪律：把预测翻译成决策&quot;">​</a></h2><ol><li><strong>条件触发式，而非时点押注</strong>。不写&quot;2020 年美股见顶&quot;，写&quot;若标普跌破年线且信用利差走阔，减仓 X%&quot;。老仇 2020-03-01 的发言中，正确的部分恰是条件（&quot;再上去&quot;）；谁若把它当成&quot;三天内必崩&quot;的时点注，涨一周就会被洗出局。</li><li><strong>仓位匹配颗粒度</strong>（对应第一节）：结构层结论配大仓位（&quot;房产税短期不出 → 不必抛售&quot;）；方向层只配对冲与保险（黄金、现金）；点位层只用于挂单分批，永不配仓位。</li><li><strong>失效条件先行</strong>。下单前写下&quot;出现什么我就承认错了&quot;。全套 24 帖中，只有 14(Kulese)给出规范句式——&quot;冲高 3150 止盈，跌破 2850 止损&quot;；kkndme 没写，于是 2021 年后只能沉默。写不出失效条件的预测，一律降级为&quot;观点&quot;。</li><li><strong>用周期定姿态，不用周期定日期</strong>。老仇的&quot;扩张加杠杆、收缩降杠杆&quot;是姿态切换器；135 的六条尾声判据是烟雾报警器——报警器响了要撤到门口，而不是预测房子几点塌。</li><li><strong>交叉验证利益</strong>。先问发帖人靠什么赚钱：9 靠读者（危险）、42 靠崇拜（危险）、14/24 靠公开写作声誉（中性）、5 靠预判正确积累信誉（相对可信）。</li><li><strong>不可证伪即弃用</strong>。问一句&quot;什么证据会推翻你？&quot;——165/42/23 全军覆没于这道题。</li><li><strong>慢变量放首位</strong>。人口、债务、技术以十年计，容错高、方向稳；把八成注意力放在慢变量上。慢变量判断对了，快变量的错误大多可以活着等回来——这是 24 篇帖子里，幸存者与出局者唯一的系统性差别。</li></ol><p><strong>一页决策卡（把全手册压缩成可贴墙的格式）：</strong></p><ul><li>我在预测哪一层？结构 / 方向 / 点位 → 决定仓位上限。</li><li>决策者是谁？他的目标函数与约束是什么？→ 五步利益分析。</li><li>现在处于周期哪个位置？尾声判据命中几条？→ 定姿态。</li><li>这个判断背后是人口慢变量还是情绪快变量？→ 定信心权重。</li><li>什么证据出现我就认错？（写不出来就不能下注）</li><li>发帖人/信息源靠什么赚钱？</li><li>动作必须是条件式：若 X 则 Y，若非 X 则按兵不动。</li></ul><hr><p><strong>结语</strong>：预测的目的不是知道未来，而是在不确定中安排行动。24 篇实测帖证明：能活下来的预测 = 利益分析定方向 + 周期定位定姿态 + 人口慢变量定结构 + 条件触发定动作 + 失效条件定退路。五件套缺一件，剩下的都只是聪明人的看法，不是可以下注的知识。</p>',62)])])}const h=o(s,[["render",u]]);export{p as __pageData,h as default};
